import test, { afterEach } from 'node:test'
import assert from 'node:assert/strict'
import { useFakeSettings, stubMeson, makeWorld, swapId, swapRecord, refusal, sleep, texts, MOVING, DONE } from './helpers.mjs'

useFakeSettings()
const { watchSwap, stopWatchingChannel } = await import('../src/watch.js')
const { getSwaps, listSwapsForAddress } = await import('../src/meson.js')
const { getTicket } = await import('../src/ticket-state.js')
const { recoverTickets } = await import('../src/recover.js')
const { onTicketMessage } = await import('../src/tickets.js')
const { CLOSING_SOON } = await import('../src/render.js')
const { extractCandidates, extractAddressCandidates } = await import('../src/extract.js')

// =============================================================================
//   Helpers
// =============================================================================

// A failed test must not leave a swap being followed: its checks would disturb the next test and keep the process alive.
afterEach(() => { for (let i = 1; i <= 20; i++) stopWatchingChannel(`c${i}`) })

/** The closing messages among what the bot posted. */
const closings = (posted) => texts(posted).filter((x) => x.includes('Transaction Completed'))

/** Start following one swap whose details embed is `embed`. */
async function follow (world, embed, id) {
  const t = getTicket(world.channel.id)
  const entry = { n: 1, swapId: id, message: embed, latest: (await getSwaps([id])).get(id) }
  t.swaps.push(entry)
  await watchSwap(t, entry)
  return entry
}

// =============================================================================
//   A failed post never ends a follow-up
// =============================================================================

test('a failed ⏳ post is retried, and the swap is still followed to its closing message', async () => {
  const id = swapId(1)
  const events = { [id]: MOVING }
  stubMeson({ events })
  const world = makeWorld('c1')
  let failures = 1
  const embed = world.message(1, world.me, {}, { failReply: () => (failures-- > 0 ? new Error('Discord 500') : null) })
  await follow(world, embed, id)
  assert.equal(texts(world.posted).length, 0)
  await sleep(1500)
  assert.equal(texts(world.posted).filter((x) => x.startsWith('⏳')).length, 1, 'the ⏳ is posted on the next check')
  events[id] = DONE
  await sleep(2500)
  assert.equal(closings(world.posted).length, 1)
  stopWatchingChannel('c1')
})

test('a failed closing message for an already finished swap is retried', async () => {
  const id = swapId(2)
  stubMeson({ events: { [id]: DONE } })
  const world = makeWorld('c2')
  let failures = 1
  const embed = world.message(1, world.me, {}, { failReply: () => (failures-- > 0 ? new Error('Discord 500') : null) })
  await follow(world, embed, id)
  assert.equal(closings(world.posted).length, 0)
  await sleep(2000)
  assert.equal(closings(world.posted).length, 1)
  stopWatchingChannel('c2')
})

test('a refused post is not repeated on every check', async () => {
  const id = swapId(3)
  const events = { [id]: MOVING }
  stubMeson({ events })
  const world = makeWorld('c3')
  const embed = world.message(1, world.me)
  await follow(world, embed, id)
  let refused = 0
  embed.reply = async () => { refused++; throw refusal() }
  events[id] = DONE
  await sleep(4500)
  assert.equal(refused, 1)
  stopWatchingChannel('c3')
})

// =============================================================================
//   Restart recovery
// =============================================================================

test('a message seen both live and in the history is handled once', async () => {
  stubMeson()
  const world = makeWorld('c4')
  const m = world.message(50, world.user, { content: `my swap ${swapId(4)} is stuck` })
  world.channel.history = [m]
  const recovering = recoverTickets(world.client)
  onTicketMessage(m)
  await recovering
  await sleep(300)
  assert.equal(texts(world.posted).filter((x) => x.startsWith('❓')).length, 1)
})

/** A ticket whose two swaps were posted before a restart: two details embeds, each with its ⏳. */
function ticketWithTwoSwaps (world, a, b) {
  const embed = (id) => ({ title: 'Meson swap — Pending', url: `https://explorer.meson.fi/swap/${id}` })
  world.channel.history = [
    world.message(10, world.me, { embeds: [embed(a)] }),
    world.message(11, world.me, { content: '⏳ x', reference: { messageId: '10' } }),
    world.message(12, world.me, { embeds: [embed(b)] }),
    world.message(13, world.me, { content: '⏳ x', reference: { messageId: '12' } }),
  ]
}

test('two swaps finishing while the bot was down: only the last closing message says "closed soon"', async () => {
  const [a, b] = [swapId(5), swapId(6)]
  stubMeson({ events: { [a]: DONE, [b]: DONE } })
  const world = makeWorld('c5')
  ticketWithTwoSwaps(world, a, b)
  await recoverTickets(world.client)
  await sleep(300)
  const all = closings(world.posted)
  assert.equal(all.length, 2)
  assert.equal(all.filter((x) => x.includes(CLOSING_SOON)).length, 1)
  assert.ok(all[1].includes(CLOSING_SOON))
})

test('recovering the same ticket twice (a reconnect) posts nothing twice', async () => {
  const [a, b] = [swapId(7), swapId(8)]
  stubMeson({ events: { [a]: DONE, [b]: MOVING } })
  const world = makeWorld('c6')
  ticketWithTwoSwaps(world, a, b)
  world.channel.history.push(world.message(14, world.user, { content: `what about ${swapId('c')}` }))
  await recoverTickets(world.client)
  await sleep(300)
  // The first pass did real work: a closing message for the finished swap, and an answer to the missed message.
  assert.equal(closings(world.posted).length, 1)
  assert.equal(texts(world.posted).filter((x) => x.startsWith('❓')).length, 1)
  const before = world.posted.length
  // A user message from the connection gap, older than the bot's last post (the bot can still post during a drop), must still be answered.
  world.channel.history.push(world.message(15, world.user, { content: `and ${swapId('c').replace(/c/g, 'e')}` }))
  await recoverTickets(world.client)
  await sleep(300)
  assert.equal(world.posted.length, before + 1, 'only the new message gets a reply')
  stopWatchingChannel('c6')
})

test('a ⏳ left behind by a stop between the two steps is removed on recovery', async () => {
  const id = swapId(9)
  stubMeson({ events: { [id]: DONE } })
  const world = makeWorld('c7')
  const processing = world.message(11, world.me, { content: '⏳ x', reference: { messageId: '10' } })
  world.channel.history = [
    world.message(10, world.me, { embeds: [{ title: 'Meson swap — Done', url: `https://explorer.meson.fi/swap/${id}` }] }),
    processing,
    world.message(12, world.me, { content: '**✅ Transaction Completed**', reference: { messageId: '10' } }),
  ]
  await recoverTickets(world.client)
  await sleep(100)
  assert.equal(processing.deleted, true)
  assert.equal(world.posted.length, 0)
})

// =============================================================================
//   A bad record from Meson
// =============================================================================

test('one malformed record does not cost the healthy swap in the same batch', async () => {
  const [good, bad] = [swapId('a'), swapId('b')]
  stubMeson({ events: { [good]: DONE }, bad: [bad] })
  const found = await getSwaps([good, bad])
  assert.equal(found.has(good), true)
  assert.equal(found.has(bad), false)
})

test('a malformed record gets the user an answer, not endless retries', async () => {
  const id = swapId('d')
  const count = stubMeson({ search: { [id]: { swapId: id } }, bad: [id] })
  const world = makeWorld('c8')
  onTicketMessage(world.message(60, world.user, { content: `swap ${id}` }))
  await sleep(2500)
  assert.equal(count.requests, 1)
  assert.equal(texts(world.posted).filter((x) => x.startsWith('❓')).length, 1)
})

test('a malformed record does not lose the rest of a wallet list', async () => {
  const [good, bad] = [swapId('e'), swapId('f')]
  globalThis.fetch = async () => new Response(JSON.stringify({ result: { list: [swapRecord(good, MOVING), swapRecord(bad, MOVING, 'garbage')] } }))
  const { swaps } = await listSwapsForAddress('anything', { size: 20 })
  assert.deepEqual(swaps.map((s) => s.swapId), [good])
})

// =============================================================================
//   Values whose shape does not say what they are
// =============================================================================

test('a bare Sui transaction hash shows its swap, not an empty wallet', async () => {
  const hash = '4'.repeat(44)
  const id = swapId('1a'.charAt(0))
  stubMeson({ events: { [id]: MOVING }, search: { [hash]: { swapId: id } } })
  const world = makeWorld('c9')
  onTicketMessage(world.message(70, world.user, { content: `my hash ${hash} thanks` }))
  await sleep(300)
  assert.equal(world.posted.filter((p) => p.embeds?.[0]?.data?.title?.startsWith('Meson swap')).length, 1)
  assert.equal(world.posted.filter((p) => p.embeds?.[0]?.data?.title?.includes('wallet')).length, 0)
  stopWatchingChannel('c9')
})

test('a bare Sui hash is still recognised in a ticket already showing a swap', async () => {
  const hash = '5'.repeat(44)
  const [first, second] = [swapId('2'), swapId('3')]
  stubMeson({ events: { [first]: MOVING, [second]: MOVING }, search: { [first]: { swapId: first }, [hash]: { swapId: second } } })
  const world = makeWorld('c10')
  onTicketMessage(world.message(71, world.user, { content: `swap ${first}` }))
  await sleep(200)
  onTicketMessage(world.message(72, world.user, { content: `and hash ${hash}` }))
  await sleep(300)
  assert.equal(world.posted.filter((p) => p.embeds?.[0]?.data?.title?.startsWith('Meson swap')).length, 2)
  stopWatchingChannel('c10')
})

test('a wallet with a swap ID shape (Sui, Starknet) lists the wallet, without "could not find"', async () => {
  const wallet = '0x' + 'ab'.repeat(32)
  stubMeson({ search: { [wallet]: { address: wallet } } })
  const world = makeWorld('c11')
  onTicketMessage(world.message(73, world.user, { content: `my wallet ${wallet}` }))
  await sleep(300)
  assert.equal(world.posted.length, 1)
  assert.equal(world.posted[0].embeds[0].data.title, 'No unfinished swaps for this wallet')
  assert.ok(!world.posted[0].embeds[0].data.description.includes('Could not find'))
})

test('a mistyped swap ID still gets "couldn\'t find", not an empty wallet', async () => {
  stubMeson()
  const world = makeWorld('c12')
  onTicketMessage(world.message(74, world.user, { content: `swap 0x${'cd'.repeat(32)}` }))
  await sleep(300)
  assert.equal(world.posted.length, 1)
  assert.ok(world.posted[0].content.startsWith('❓'))
})

test('a wallet Meson answers for as a wallet still lists it, with one search first', async () => {
  const wallet = '4'.repeat(40) + 'abcd'
  let searches = 0
  stubMeson()
  const stubbed = globalThis.fetch
  globalThis.fetch = async (url) => { if (String(url).includes('/search?')) searches++; return stubbed(url) }
  const world = makeWorld('c13')
  onTicketMessage(world.message(75, world.user, { content: `wallet ${wallet}` }))
  await sleep(300)
  assert.equal(searches, 1)
  assert.equal(world.posted[0].embeds[0].data.title, 'No unfinished swaps for this wallet')
})

test('extraction covers the less common chains', () => {
  const short = '0x' + '5'.repeat(63)
  const ton = 'Ab-_'.repeat(10) + 'Ab-'
  assert.deepEqual(extractCandidates(`hash ${short}`), [short])
  assert.ok(extractCandidates(`https://tonviewer.com/transaction/${ton}`).includes(ton))
  const tonWallet = 'EQ' + 'Ab-_'.repeat(11) + 'Ab'
  assert.deepEqual(extractAddressCandidates(`wallet ${tonWallet}`, { allowFallback: false }), [tonWallet])
  const ckbWallet = 'ckb1qzda0cr08m85hc8jlnfp3zer7xulejywt49kt2rr0vthywaa50xwsq'
  assert.deepEqual(extractAddressCandidates(`wallet ${ckbWallet}`, { allowFallback: false }), [ckbWallet])
})
